PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT ?person ?personLabel ?birth ?death ?ageYears WHERE {
  VALUES ?person {
    dbr:John-Roger_Hinkins dbr:Charles_Harpur
  }
  ?person dbo:birthDate ?birth .
  ?person dbo:deathDate ?death .
  BIND((YEAR(?death) - YEAR(?birth)) AS ?rawYears)
  BIND(IF((MONTH(?death) < MONTH(?birth)) ||((MONTH(?death) = MONTH(?birth)) &&(DAY(?death) < DAY(?birth))) , 1 , 0) AS ?subtract)
  BIND((?rawYears - ?subtract) AS ?ageYears)
  OPTIONAL {
    ?person rdfs:label ?personLabel .
    FILTER(lang(?personLabel) = "en")
  }
}
ORDER BY DESC(?ageYears)
LIMIT 2
